// The file this demo ends on: it cannot load at the start and it runs at the end.

import chalk from 'chalk';
import { satisfies } from 'semver';

/** Green when the installed release satisfies what we asked for, red when it does not. */
export function verdict(version, range) {
  return satisfies(version, range) ? chalk.green.bold('ok') : chalk.red('too old');
}

project.src/group.mjs:
// Two lodash calls, which between them are most of what lodash is used for.

import { groupBy, get } from 'lodash';

export const byKind = (rows) => groupBy(rows, (row) => get(row, 'meta.kind', 'unknown'));

export const kinds = (rows) => Object.keys(byKind(rows)).sort().join(', ');

project.src/files.mjs:
// One package a machine may replace and one it may not, in the same file on purpose.

import { minimatch } from 'minimatch';
import { glob } from 'glob';

export async function sources(root) {
  const found = await glob('**/*.mjs', { cwd: root });
  return found.filter((file) => minimatch(file, 'src/**'));
}

